# 1. Arguments the extractor must provide
list_of_arguments_to_read = {
    "tool_name": str,               # name of the tool to be called
    "fund_id": str,                 # identifier of the fund (purchase/redemption/recommendation)
    "amount": float,                # monetary amount for purchase/redemption
    "rationale": str,               # text explaining recommendation
    "has_get_customer_profile": bool,   # True if get_customer_profile was called earlier in the episode
    "has_check_suitability": bool,      # True if check_suitability was called earlier in the episode
    "suitability_match": bool,          # Result of check_suitability (match == true)
    "penalty_disclosed": bool,          # True if the 1.5 % early‑redemption penalty was disclosed to the user
}

# 2. Policy constants
ALWAYS_ALLOWED = {
    "get_customer_profile",
    "search_funds",
    "check_suitability",
    "reject_request",
    "escalate_to_compliance",
    "escalate_to_human",
}
PROHIBITED_RATIONALE_PHRASES = [
    "principal guarantee",
    "guaranteed return",
    "exaggerated return",
    "guarantee",
    "risk‑free",
]

# 3. Policy function
def policy(arguments: dict) -> tuple[bool, str]:
    """Allow or deny a tool call based on extracted structured arguments."""
    tool = arguments.get("tool_name")
    if not tool:
        return False, "Missing required argument: tool_name."

    # Unrestricted tools
    if tool in ALWAYS_ALLOWED:
        return True, f"Tool '{tool}' is always allowed."

    # ---- Critical purchase ----
    if tool == "execute_purchase":
        if not arguments.get("has_get_customer_profile"):
            return False, "execute_purchase requires a prior get_customer_profile call."
        if not arguments.get("has_check_suitability"):
            return False, "execute_purchase requires a prior check_suitability call."
        if not arguments.get("suitability_match"):
            return False, "execute_purchase requires suitability_match == true."
        if arguments.get("fund_id") is None:
            return False, "execute_purchase missing required argument: fund_id."
        if arguments.get("amount") is None:
            return False, "execute_purchase missing required argument: amount."
        return True, "execute_purchase approved."

    # ---- Critical redemption ----
    if tool == "execute_redemption":
        if not arguments.get("penalty_disclosed"):
            return False, "execute_redemption requires prior disclosure of the 1.5 % early‑redemption penalty."
        if arguments.get("fund_id") is None:
            return False, "execute_redemption missing required argument: fund_id."
        if arguments.get("amount") is None:
            return False, "execute_redemption missing required argument: amount."
        return True, "execute_redemption approved."

    # ---- High‑level recommendation ----
    if tool == "recommend_product":
        if not arguments.get("has_check_suitability"):
            return False, "recommend_product requires a prior check_suitability call."
        if not arguments.get("suitability_match"):
            return False, "recommend_product requires suitability_match == true."
        rationale = arguments.get("rationale")
        if not rationale:
            return False, "recommend_product missing required argument: rationale."
        low_rationale = rationale.lower()
        if any(phrase in low_rationale for phrase in PROHIBITED_RATIONALE_PHRASES):
            return False, "rationale contains prohibited guarantee or exaggerated‑return language."
        return True, "recommend_product approved."

    # ---- Other tools (not listed in policy) ----
    return True, f"Tool '{tool}' is not subject to additional policy checks."

